import {candidates,discoveryCandidates,validateBackup,rankMovies,taste,affinity,mergeRecords,parseScore,isStale,DAY} from './core.js';
import {seeds} from './demo.js';
import {configureCloud,cloudUser,cloudEnabled,login,signup,logout,syncRecords,syncFolders as syncFoldersCloud} from './cloud.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const imageURL=v=>typeof v==='string'&&/^https:\/\/image\.tmdb\.org\/t\/p\/(w\d+|original)\/[\w.-]+$/.test(v)?v:'';
let storeKey='poppy-v2-guest',records={},storageError=false;
function loadRecords(){try{let raw=localStorage.getItem(storeKey);if(!raw&&storeKey==='poppy-v2-guest')raw=localStorage.getItem('poppy-v1');records=raw?validateBackup(JSON.parse(raw)):{};}catch{records={};storageError=true;}}
loadRecords();
let catalog=[...seeds],mode='connecting',tab='home',pick=null,opened=null,genre='',max=999,onlyPending=false,surprise=false,searchVersion=0,detailVersion=0,loadVersion=0,config={},apiError='',syncStatus='Solo en este navegador',syncing=false,syncTimer=null;
let folders=[],folderId=null,folderQuery='',folderResults=[],folderPage=1,folderTotal=1,folderRequest=0,undoAction=null,undoTimer=null;
let duelA='',duelB='',duelWinner=null;
let bulk=false,selected=new Set(),query='',searchResults=[],searchPageNum=1,totalPages=1,listOrder='recent',listQuery='',month='';
const dirty=new Set();
function activeRecords(){return Object.values(records).filter(r=>!r.deleted);}
function rec(id){return records[id]?.deleted?null:records[id];}
function persist(){try{localStorage.setItem(storeKey,JSON.stringify({version:2,records}));return true;}catch{toast('No se ha podido guardar en este navegador. Exporta una copia en Ajustes.');return false;}}
function put(id,patch){const old=rec(id)||{movie:getMovie(id),status:'none',score:null,note:'',date:''};records[id]={...old,...patch,updatedAt:Math.max(Date.now(),(records[id]?.updatedAt||0)+1)};dirty.add(String(id));const ok=persist();clearTimeout(syncTimer);if(cloudUser()&&cloudEnabled())syncTimer=setTimeout(()=>syncNow(),1200);return ok;}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',12000);}
function allMovies(){const map=new Map();for(const m of [...activeRecords().map(r=>r.movie),...catalog]){const old=map.get(m.id);if(!old||(!old.full&&m.full)||(!old.full&&!m.full)||Date.parse(m.fetchedAt||0)>Date.parse(old.fetchedAt||0))map.set(m.id,m);}return [...map.values()];}
function getMovie(id){return allMovies().find(m=>m.id===Number(id));}
function putMovie(m){const i=catalog.findIndex(x=>x.id===m.id);if(i<0)catalog.push(m);else catalog[i]=m;}
function poster(m){const src=imageURL(m.poster);return `<div class="poster">${src?`<img data-poster="${m.id}" src="${esc(src)}" alt="Cartel de ${esc(m.title)}" loading="lazy">`:`<span><img class="fallback-logo" src="logo.svg" alt="">${esc(m.title)}<small>Cartel no disponible</small></span>`}</div>`;}
const FOLDER_ICONS=['🎬','🍿','❤️','🎃','👩‍❤️‍👨','✨','😱','🎄','🌧️','⭐'];
function normalizeFolder(f){return {id:f.id,name:String(f.name||'Colección').slice(0,70),movies:Array.isArray(f.movies)?f.movies.map(Number).filter(Number.isFinite):[],updatedAt:Number(f.updatedAt||0),deleted:!!f.deleted,icon:(f.icon||'🎬').slice(0,8),banner:typeof f.banner==='string'?f.banner:''};}
function folderVisual(folder,mode='card'){const f=normalizeFolder(folder||{}),hasBanner=!!f.banner;const icon=`<span class="${hasBanner?'folder-icon-badge':'folder-icon-large'}" aria-hidden="true">${esc(f.icon||'🎬')}</span>`;if(mode==='cover')return `<div class="collection-cover ${hasBanner?'has-banner':''}">${hasBanner?`<img src="${esc(f.banner)}" alt="Banner de ${esc(f.name)}">`:`<div class="folder-icon-large">${esc(f.icon||'🎬')}</div>`}${hasBanner?icon:''}</div>`;if(mode==='preview')return `<div class="folder-banner-preview">${hasBanner?`<img src="${esc(f.banner)}" alt="Banner de ${esc(f.name)}">`:'<div class="folder-empty-banner">Sube una imagen horizontal desde tu galería para darle un toque propio.</div>'}${icon}</div>`;return `<div class="folder-visual ${hasBanner?'has-banner':''}">${hasBanner?`<img src="${esc(f.banner)}" alt="Banner de ${esc(f.name)}">`:icon}${hasBanner?icon:''}</div>`;}
async function fileToDataURL(file){return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(Error('No se pudo leer la imagen.'));reader.readAsDataURL(file);});}
async function compressFolderBanner(file){if(!file)throw Error('Selecciona una imagen.');if(!file.type.startsWith('image/'))throw Error('Elige una imagen de tu galería.');const url=await fileToDataURL(file);const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('No se pudo abrir la imagen.'));i.src=url;});const targetRatio=3/1;let sx=0,sy=0,sw=img.width,sh=img.height;const ratio=img.width/img.height;if(ratio>targetRatio){sw=img.height*targetRatio;sx=(img.width-sw)/2;}else if(ratio<targetRatio){sh=img.width/targetRatio;sy=(img.height-sh)/2;}const width=Math.min(960,Math.round(sw));const height=Math.round(width/targetRatio);const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(img,sx,sy,sw,sh,0,0,width,height);const data=canvas.toDataURL('image/jpeg',0.82);if(data.length>320000)throw Error('La imagen sigue siendo demasiado grande. Usa una más ligera.');return data;}

const attempted=new Set();
document.addEventListener('error',async e=>{const img=e.target;if(img.matches?.('[data-person]')){const span=document.createElement('span');span.className='person-placeholder';span.textContent=img.alt.split(' ').map(x=>x[0]).slice(0,2).join('');img.replaceWith(span);return;}if(!img.matches?.('[data-poster]'))return;const id=Number(img.dataset.poster),m=getMovie(id);if(!m)return;const alternatives=(m.posterAlternatives||[]).filter(imageURL);const n=Number(img.dataset.attempt||0);if(n<alternatives.length){img.dataset.attempt=n+1;img.src=alternatives[n];return;}if(mode==='live'&&!attempted.has(id)){attempted.add(id);try{const fresh=await api('?id='+id);putMovie(fresh);const candidate=[fresh.poster,...fresh.posterAlternatives||[]].filter(imageURL).find(u=>u!==img.src);if(candidate&&img.isConnected){img.src=candidate;img.dataset.attempt=999;return;}}catch{}}if(img.isConnected){const span=document.createElement('span');span.textContent=m.title+' · Cartel no disponible';img.replaceWith(span);}},true);
function card(m){const r=rec(m.id);return `<article class="card-wrap">${bulk&&tab==='search'?`<label class="bulk-check"><input type="checkbox" data-select="${m.id}" ${selected.has(m.id)?'checked':''}> Seleccionar</label>`:''}<button class="card" data-movie="${m.id}">${poster(m)}<h3>${esc(m.title)}</h3><small>${esc(m.year)}${r?.status==='seen'?` · ★ ${r.score??'Sin puntuar'}`:r?.status==='pending'?' · Pendiente':''}</small></button></article>`;}
const grid=movies=>movies.length?`<div class="grid">${movies.map(card).join('')}</div>`:'<div class="empty">No hay películas con estas condiciones.<p class="muted">Prueba otra búsqueda o cambia los filtros.</p><button class="secondary" data-tab="search">Descubrir películas</button></div>';
function available(){return candidates(allMovies(),records,genre,max,onlyPending);}
function discoverable(){return discoveryCandidates(allMovies(),records,genre,max);}
function chosen(){return activeRecords().filter(r=>r.chosenAt&&r.status==='pending').sort((a,b)=>b.chosenAt-a.chosenAt)[0]?.movie;}
function choose(){const options=onlyPending?available():discoverable();const list=options.filter(m=>m.id!==pick?.id);const source=list.length?list:options;const ranked=rankMovies(source,records);const pool=surprise?ranked.slice(0,Math.min(12,ranked.length)):ranked.slice(0,Math.min(5,ranked.length));const weights=pool.map((m,i)=>Math.max(1,11-i));let spin=Math.random()*weights.reduce((x,y)=>x+y,0);pick=pool.find((m,i)=>(spin-=weights[i])<0)||pool[0]||null;}
function recommendationReason(m){const weights=taste(records);const liked=m.genres.filter(g=>weights[g]>0).sort((a,b)=>weights[b]-weights[a]);return liked.length?'Una propuesta basada en tus buenas notas a películas de '+liked.slice(0,2).join(' y ')+'.': 'Una propuesta para explorar nuevos géneros. Cuantas más películas puntúes, mejor te conocerá Poppy.';}
function render(){document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false');});if(tab==='home')home();if(tab==='search')searchPage();if(['pending','seen','dismissed'].includes(tab))listPage();if(tab==='settings')settings();if(tab==='folders')foldersPage();if(tab==='duel')duelPage();}
function duelPage(){
 const pending=activeRecords().filter(r=>r.status==='pending'&&r.movie).map(r=>r.movie).sort((a,b)=>a.title.localeCompare(b.title,'es'));
 if(!pending.some(m=>String(m.id)===String(duelA)))duelA='';
 if(!pending.some(m=>String(m.id)===String(duelB)))duelB='';
 if(pending.length<2){$('#main').innerHTML=`<span class="eyebrow">UNA DECISIÓN DE CINE</span><h1>Duelo de pelis.</h1><p class="muted">Guarda al menos dos películas en Pendientes para enfrentarlas.</p><button class="primary" data-tab="pending">Ir a pendientes</button>`;return;}
 const options=(selected)=>`<option value="">Selecciona una pendiente…</option>${pending.map(m=>`<option value="${m.id}" ${String(m.id)===String(selected)?'selected':''}>${esc(m.title)} (${esc(m.year)})</option>`).join('')}`;
 const a=pending.find(m=>String(m.id)===String(duelA)),b=pending.find(m=>String(m.id)===String(duelB));
 const winner=duelWinner&&[a?.id,b?.id].includes(duelWinner)?pending.find(m=>m.id===duelWinner):null;
 $('#main').innerHTML=`<span class="eyebrow">CARA O CRUZ CINEMATOGRÁFICA</span><h1>Duelo de pelis.</h1><p class="muted">Elige dos películas de tu lista de pendientes. Poppy decidirá al azar cuál ver. Tienen exactamente un 50 % de posibilidades cada una.</p><div class="duel-actions"><button class="secondary" id="duelRandom" type="button">🎲 Elegir dos pendientes al azar</button></div><div class="duel-pickers"><label>Primera película<select id="duelA">${options(duelA)}</select></label><span class="duel-vs">VS</span><label>Segunda película<select id="duelB">${options(duelB)}</select></label></div><div class="duel-arena">${[a,b].map(m=>`<div class="duel-contender">${m?`${poster(m)}<h3>${esc(m.title)}</h3><small>${esc(m.year)}</small>`:'<div class="duel-placeholder">Elige una película</div>'}</div>`).join('<strong class="duel-vs">VS</strong>')}</div><div class="duel-actions"><button class="primary" id="duelFight" ${!a||!b||a.id===b.id?'disabled':''}>¡Que empiece el duelo!</button>${a&&b&&a.id===b.id?'<p class="muted">Elige dos películas diferentes.</p>':''}</div>${winner?`<section class="duel-result" aria-live="polite"><span class="eyebrow">LA GANADORA ES…</span><h2>${esc(winner.title)}</h2><p>Elegida al azar entre tus dos pendientes.</p><button class="secondary" data-movie="${winner.id}">Ver su ficha ↗</button></section>`:''}`;
 $('#duelRandom').onclick=()=>{const shuffled=[...pending];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]];}duelA=String(shuffled[0].id);duelB=String(shuffled[1].id);duelWinner=null;duelPage();};$('#duelA').onchange=e=>{duelA=e.target.value;duelWinner=null;duelPage();};$('#duelB').onchange=e=>{duelB=e.target.value;duelWinner=null;duelPage();};$('#duelFight').onclick=()=>{duelWinner=Math.random()<.5?a.id:b.id;duelPage();};
}
function removeFromCurrentFolder(id){const current=folderCurrent();if(!current||!current.movies.some(x=>Number(x)===Number(id)))return;const previous=[...current.movies];current.movies=current.movies.filter(x=>Number(x)!==Number(id));current.updatedAt=Math.max(Date.now(),Number(current.updatedAt||0)+1);commitFolders();toast('Película quitada solo de esta colección.');const button=document.createElement('button');button.className='toast-undo';button.textContent='Deshacer';button.onclick=()=>{const f=folders.find(x=>x.id===current.id);if(!f||f.deleted)return;if(!f.movies.some(x=>Number(x)===Number(id))){f.movies=previous;f.updatedAt=Math.max(Date.now(),Number(f.updatedAt||0)+1);commitFolders();}toast('Película recuperada en la colección.');};$('#toast').append(button);}
function home(){const fixed=chosen();if(!pick||!(onlyPending?available():discoverable()).some(m=>m.id===pick.id))choose();const m=fixed||pick;$('#main').innerHTML=`<div class="intro"><span class="eyebrow">TU BUTACA TE ESTÁ ESPERANDO</span><h1>Este finde, <em>dale al play.</em></h1><p class="muted">Tu película, tus palomitas, tu momento.</p></div>${mode!=='live'?`<div class="notice">${mode==='connecting'?'Conectando con tu catálogo…':esc(apiError||'Estás viendo la colección de muestra.')} <button class="textbtn" data-tab="settings">Ver conexión y ayuda →</button></div>`:''}<div class="filters home-filters"><select id="genre" aria-label="Género"><option value="">Todos los géneros</option>${[...new Set([...Object.values(config.genres||{}),...allMovies().flatMap(m=>m.genres)])].sort().map(g=>`<option ${genre===g?'selected':''}>${esc(g)}</option>`).join('')}</select><select id="duration" aria-label="Duración máxima">${[[999,'Tengo toda la tarde'],[90,'Hasta 90 minutos'],[120,'Hasta 2 horas'],[150,'Hasta 2 h 30']].map(([v,t])=>`<option value="${v}" ${max===v?'selected':''}>${t}</option>`).join('')}</select><select id="strategy" aria-label="Tipo de recomendación"><option value="taste" ${!surprise?'selected':''}>Según mis gustos</option><option value="surprise" ${surprise?'selected':''}>Sorpréndeme según mis gustos</option></select><label class="inline-check"><input id="onlyPending" type="checkbox" ${onlyPending?'checked':''}> Solo pendientes</label></div>${m?`<section class="hero"><div><div class="ticket">SESIÓN PRIVADA &nbsp; / &nbsp; SOLO PARA TI</div><span class="eyebrow">${fixed?'TU PELI PARA ESTE FINDE':'LA PROPUESTA DE HOY'}</span><h2>${esc(m.title)}</h2><p class="muted">${esc(m.year)} · ${m.runtime?esc(m.runtime)+' min':'Duración en la ficha'} ${m.director?'· '+esc(m.director):''}</p><div>${m.genres.map(g=>`<span class="tag">${esc(g)}</span>`).join('')}</div><p class="description">${esc(m.overview)}</p><p class="muted">${fixed?'La guardamos aquí hasta que la veas o cambies de plan.':esc(recommendationReason(m))}</p><div class="actions hero-actions"><button class="primary" data-movie="${m.id}">Ver ficha ↗</button>${fixed?`<button class="secondary" data-action="unchoose" data-id="${m.id}">Cambiar de plan</button><button class="secondary" data-action="finish" data-id="${m.id}">Ya la he visto</button>`:`<button class="secondary" data-action="choose" data-id="${m.id}">Esta es la del finde</button><button class="secondary" data-action="later" data-id="${m.id}">Hoy no</button>`}</div></div>${poster(m)}</section>`:'<div class="empty">No quedan propuestas con estos filtros. Puedes cargar más o cambiar de plan.</div>'}<div class="sectionhead"><h2>Más historias por descubrir</h2><button class="textbtn" id="moreRecommendations">Buscar más propuestas ↻</button></div>${fixed?'<p class="muted">Los filtros se aplican a las nuevas propuestas; tu elección del finde sigue reservada.</p>':''}${grid((surprise?discoverable():rankMovies(discoverable(),records)).filter(x=>x.id!==m?.id).slice(0,10))}`;
 $('#genre').onchange=async e=>{genre=e.target.value;pick=null;home();await loadRecommendations();};$('#duration').onchange=async e=>{max=Number(e.target.value);pick=null;home();await loadRecommendations();};$('#onlyPending').onchange=e=>{onlyPending=e.target.checked;pick=null;home();};$('#strategy').onchange=e=>{surprise=e.target.value==='surprise';choose();home();};$('#moreRecommendations').onclick=async()=>{if(mode==='live')await loadRecommendations(true);else{choose();home();}};}
let discoverPage=1;
async function loadRecommendations(more=false){if(mode!=='live'||onlyPending)return;const version=++loadVersion;discoverPage=more?Math.min(discoverPage+1,50):1;const gid=Object.entries(config.genres||{}).find(([,g])=>g===genre)?.[0]||'';try{const d=await api(`?page=${discoverPage}&genre=${gid}&max=${max}`);if(version!==loadVersion)return;const details=max<999?await Promise.all(d.movies.slice(0,12).map(m=>api('?id='+m.id).catch(()=>m))):d.movies;details.forEach(putMovie);choose();if(tab==='home')home();}catch(e){toast(e.message);}}
function searchPage(){searchVersion++;$('#main').innerHTML=`<span class="eyebrow">ENCUENTRA TU PRÓXIMA HISTORIA</span><h1>Una peli en mente…</h1><p class="muted">Busca una película o marca de golpe las que ya has visto.</p><form id="searchForm" class="filters"><input id="query" value="${esc(query)}" placeholder="Título de la película…" aria-label="Título de la película" maxlength="150"><button class="primary">Buscar</button><button class="secondary" id="bulkToggle" type="button">${bulk?'Terminar selección':'Marcar varias como vistas'}</button></form>${bulk?`<div class="notice"><span id="selectionCount">${selected.size}</span> seleccionadas <button id="bulkSave" class="primary">Marcar como vistas</button><p class="muted">No se asignará una fecha inventada. Después puedes añadir la fecha y tu nota en cada ficha.</p></div>`:''}<p class="muted">${mode==='live'?'Búsqueda en TMDB · Tus vistas se conservan, pero no se recomiendan.':'Muestra local. Configura o revisa la conexión en Ajustes.'}</p><div id="results">${grid(searchResults.length||query?searchResults:catalog.slice(0,20))}</div><div class="actions"><button id="loadMore" class="secondary" ${mode!=='live'||searchPageNum>=totalPages?'hidden':''}>Cargar más resultados</button></div>`;
 $('#searchForm').onsubmit=e=>{e.preventDefault();query=$('#query').value.trim();searchPageNum=1;runSearch(false);};$('#bulkToggle').onclick=()=>{bulk=!bulk;searchPage();};$('#loadMore').onclick=()=>runSearch(true);if($('#bulkSave'))$('#bulkSave').onclick=()=>{if(!selected.size)return toast('Selecciona al menos una película.');for(const id of selected)put(id,{movie:getMovie(id),status:'seen',chosenAt:0,skipUntil:0});const n=selected.size;selected.clear();render();toast(n+' películas marcadas como vistas.');};}
async function runSearch(more){const version=++searchVersion;if(!more)$('#results').innerHTML='<p class="loading">Buscando historias…</p>';$('#loadMore').disabled=true;try{const page=more?searchPageNum+1:1;const d=mode==='live'?await api('?q='+encodeURIComponent(query)+'&page='+page):{movies:seeds.filter(m=>m.title.toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es'))),totalPages:1};if(tab!=='search'||version!==searchVersion)return;d.movies.forEach(putMovie);searchResults=more?[...new Map([...searchResults,...d.movies].map(m=>[m.id,m])).values()]:d.movies;searchPageNum=page;totalPages=d.totalPages||1;searchPage();}catch(e){if(tab==='search'&&version===searchVersion){$('#results').innerHTML=`<div class="empty">${esc(e.message)}</div>`;$('#loadMore').disabled=false;}}}
function listPage(){const seen=tab==='seen',dismissed=tab==='dismissed';let items=activeRecords().filter(r=>r.status===(seen?'seen':dismissed?'dismissed':'pending'));const all=items,scores=items.filter(r=>r.score!=null);items=items.filter(r=>r.movie.title.toLocaleLowerCase('es').includes(listQuery.toLocaleLowerCase('es'))&&(!month||!seen||r.date?.startsWith(month)));items.sort((a,b)=>listOrder==='rating'?(b.score??-1)-(a.score??-1):listOrder==='title'?a.movie.title.localeCompare(b.movie.title):listOrder==='year-desc'?(Number(b.movie.year)||0)-(Number(a.movie.year)||0):listOrder==='year-asc'?(Number(a.movie.year)||9999)-(Number(b.movie.year)||9999):(b.date||'').localeCompare(a.date||'')||(b.updatedAt||0)-(a.updatedAt||0));$('#main').innerHTML=`<span class="eyebrow">TU COLECCIÓN PERSONAL</span><div class="collection-heading"><h1>${seen?'Mi diario de cine':dismissed?'Ahora no me interesan.':'Para otro día.'}</h1>${!seen&&!dismissed?`<span class="popcorn-count" role="img" aria-label="${all.length} películas pendientes"><img src="popcorn.svg" alt=""><b>${all.length}</b></span>`:''}</div><p class="muted">${seen?'Cada película, una pequeña historia contigo.':dismissed?'Abre una ficha para devolverla a pendientes.':'Tus próximos planes de sofá.'}</p>${seen?`<div class="stats"><div><strong>${all.length}</strong><p>Películas vistas</p></div><div><strong>${scores.length?(scores.reduce((s,r)=>s+r.score,0)/scores.length).toFixed(2):'—'}</strong><p>Mi nota media</p></div><div><strong>${all.filter(r=>r.score>=9).length}</strong><p>Favoritas · 9 o más</p></div></div>`:''}<div class="filters"><input id="listQuery" value="${esc(listQuery)}" placeholder="Buscar en mi colección" aria-label="Buscar en mi colección"><select id="listOrder" aria-label="Ordenar"><option value="recent">Más recientes</option><option value="rating">Mi nota más alta</option><option value="title">Título A–Z</option><option value="year-desc">Año · más recientes</option><option value="year-asc">Año · más antiguas</option></select>${seen?`<input id="month" type="month" aria-label="Mes de visionado" value="${esc(month)}">`:''}</div>${grid(items.map(r=>r.movie))}`;$('#listOrder').value=listOrder;$('#listOrder').onchange=e=>{listOrder=e.target.value;listPage();};$('#listQuery').onchange=e=>{listQuery=e.target.value;listPage();};if($('#month'))$('#month').onchange=e=>{month=e.target.value;listPage();};}
async function api(params){const r=await fetch('./api/movies'+params,{signal:AbortSignal.timeout(28000)});let v;try{v=await r.json();}catch{throw Error('La API no está disponible. Despliega en Vercel, no en GitHub Pages.');}if(!r.ok)throw Error(v.error||'No se pudo cargar el catálogo.');return v;}
function people(m,role){const list=(m.people||[]).filter(p=>p.role===role);return `<h3>${role==='Dirección'?'Dirección':'Reparto principal'}</h3>${list.length?`<div class="people">${list.map(p=>`<a class="person" target="_blank" rel="noopener" href="https://www.themoviedb.org/person/${Number(p.id)}">${imageURL(p.photo)?`<img data-person src="${esc(p.photo)}" alt="${esc(p.name)}" loading="lazy">`:`<span class="person-placeholder">${esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`}<b>${esc(p.name)}</b><small>${esc(p.character||role)}</small></a>`).join('')}</div>`:`<p class="muted">${esc(role==='Dirección'?m.director||'Sin datos':m.cast.join(', ')||'Sin datos')}${m.demo?' · Fotos disponibles al conectar TMDB.':''}</p>`}`;}
function ratings(m){const list=[['imdb','IMDb'],['letterboxd','Letterboxd'],['tomatoes','Rotten Tomatoes · crítica'],['audience','Rotten Tomatoes · público']];return `<h3>Puntuaciones de las plataformas</h3>${m.ratingsState==='unconfigured'||m.demo?'<div class="notice">Falta conectar las puntuaciones. Añade <b>MDBLIST_API_KEY</b> en Vercel y haz Redeploy. <button class="textbtn" id="ratingsHelp">Ver los pasos →</button></div>':''}<div class="ratings">${list.map(([key,name])=>{const r=m.ratings.find(x=>x.key===key);return `<div class="rating"><span>${name}</span><b>${esc(r?.Value||'—')}</b><small>${r?.Value?'':m.ratingsState==='error'?'Consulta fallida':m.ratingsState==='unconfigured'||m.demo?'Pendiente de conexión':'Sin dato disponible'}</small></div>`;}).join('')}</div><p class="muted">${m.ratingsFetchedAt?'Última consulta: '+esc(new Date(m.ratingsFetchedAt).toLocaleString('es-ES'))+'. ':''}Se vuelven a consultar al abrir la ficha tras 24 horas. El proveedor puede llevar retraso respecto a las webs. Rotten Tomatoes muestra porcentajes de aprobación.</p>${m.ratingsState==='error'?'<p class="notice">No se pudieron actualizar todas las puntuaciones. Los últimos valores disponibles se conservan con su fecha.</p>':''}`;}
async function openMovie(id,finish=false){opened=getMovie(id);if(!opened)return;const version=++detailVersion;detail();if(!$('#detail').open)$('#detail').showModal();if(finish){quickStatus('seen');return;}if(mode==='live'&&(isStale(opened)||opened.ratingsState==='error'||(config.mdb&&opened.ratingsState==='unconfigured'))){const old=opened;$('#dataMessage').textContent='Actualizando ficha, imágenes y puntuaciones…';try{const fresh=await api('?id='+id);if(fresh.ratingsState==='error'&&old.ratings?.some(x=>x.Value)){fresh.ratings=fresh.ratings.map(x=>x.Value?x:old.ratings.find(r=>r.key===x.key&&r.Value)||x);fresh.ratingsFetchedAt=old.ratingsFetchedAt;}putMovie(fresh);if(rec(id)){records[id].movie=fresh;persist();}if(version!==detailVersion)return;const draft=getDraft();opened=fresh;detail();restoreDraft(draft);}catch(e){if(version===detailVersion){$('#dataMessage').textContent=e.message;toast(e.message);}}}}
function getDraft(){return Object.fromEntries(['status','score','date','note'].map(k=>[k,$('#'+k)?.value||'']));}
function restoreDraft(d){for(const [k,v] of Object.entries(d))if($('#'+k))$('#'+k).value=v;updateStatusControls();}
function setFinished(){quickStatus('seen');$('#score').focus();}
function updateStatusControls(){const state=$('#status').value;document.querySelectorAll('[data-quick-status]').forEach(b=>{const active=b.dataset.quickStatus===state;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});$('#personal').hidden=state!=='seen';}
function saveUndo(id,previous){undoAction={id,previous};clearTimeout(undoTimer);toast('Cambio guardado. Puedes deshacerlo durante unos segundos.');const button=document.createElement('button');button.className='toast-undo';button.textContent='Deshacer';button.onclick=()=>{if(!undoAction)return;const {id,previous}=undoAction;undoAction=null;const current=rec(id);if(previous){put(id,{...previous,updatedAt:Date.now()});}else if(current){put(id,{deleted:true});}toast('Acción deshecha.');render();};$('#toast').append(button);undoTimer=setTimeout(()=>{undoAction=null;},12000);}
function quickStatus(state){const previous=rec(opened.id)?{...rec(opened.id)}:null;const old=rec(opened.id)||{},date=state==='seen'?old.date||today():old.date||'';const ok=put(opened.id,{movie:opened,status:state,date,chosenAt:state==='pending'?old.chosenAt||0:0,skipUntil:0});$('#status').value=state;if(state==='seen'&&!$('#date').value)$('#date').value=date;updateStatusControls();if(state==='seen'){if(ok){toast('Marcada como vista. Pon tu nota y pulsa «Guardar mi nota».');$('#score').focus();}return;}if(ok)saveUndo(opened.id,previous);$('#detail').close();render();}
function detail(){const m=opened,r=rec(m.id)||{};$('#detailContent').innerHTML=`<div class="status-toolbar" aria-label="Estado de la película"><div class="status-buttons"><button type="button" data-quick-status="pending" aria-pressed="false"><span aria-hidden="true">＋</span> Pendiente</button><button type="button" data-quick-status="seen" aria-pressed="false"><span aria-hidden="true">✓</span> Vista</button><button type="button" data-quick-status="dismissed" aria-pressed="false"><span aria-hidden="true">−</span> No me interesa</button></div><small>Pendiente y No me interesa se guardan al pulsar. En Vista, añade y guarda tu nota.</small></div><input type="hidden" id="status" value="${esc(r.status||'none')}"><div class="details">${poster(m)}<div><span class="eyebrow">UNA HISTORIA PARA TI</span><h2>${esc(m.title)}</h2><p class="muted">${esc(m.year)} · ${m.runtime?esc(m.runtime)+' min':'Duración sin consultar'}</p>${m.genres.map(g=>`<span class="tag">${esc(g)}</span>`).join('')}<div class="actions compact"><button class="secondary" data-action="choose" data-id="${m.id}">Esta es la del finde</button><button class="textbtn" data-action="later" data-id="${m.id}">Hoy no</button></div><p>${esc(m.overview)}</p><div class="actions"><a class="textbtn" target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent(m.title+' trailer español')}">Buscar tráiler ↗</a><a class="textbtn" target="_blank" rel="noopener" href="https://www.justwatch.com/es/buscar?q=${encodeURIComponent(m.title)}">Dónde verla ↗</a></div><p id="dataMessage" class="muted" role="status">${m.demo?'Ficha de muestra; conecta TMDB para completarla.':''}</p></div></div><div class="detail-collection"><button type="button" class="secondary" id="chooseFolderForMovie">＋ Añadir a colección</button><div id="movieFolders" hidden></div></div><form id="personal" class="personal-panel"><div class="my-rating"><div><label for="score">Mi nota · sobre 10</label><input id="score" type="text" inputmode="decimal" maxlength="10" value="${esc(r.score??'')}" placeholder="8,75"></div><button class="primary" type="submit">Guardar mi nota</button></div><details><summary>Fecha y comentario</summary><label for="date">Fecha en que la vi</label><input id="date" type="date" max="${today()}" value="${esc(r.date||'')}"><label for="note">¿Qué te ha parecido?</label><textarea id="note" maxlength="5000" placeholder="Ese final, esa escena, esa sensación…">${esc(r.note||'')}</textarea><p class="muted">La fecha y el comentario se guardan junto con tu nota.</p></details></form>${ratings(m)}${people(m,'Dirección')}${people(m,'Reparto')}<div class="actions"><button class="textbtn" id="remove">${tab==='folders'&&folderCurrent()?.movies.some(id=>Number(id)===m.id)?'Quitar de esta carpeta':'Quitar de mis listas personales'}</button></div>`;
 updateStatusControls();document.querySelectorAll('[data-quick-status]').forEach(b=>b.onclick=()=>quickStatus(b.dataset.quickStatus));
 $('#chooseFolderForMovie').onclick=()=>{const target=$('#movieFolders');target.hidden=!target.hidden;if(target.hidden)return;const visible=folders.filter(f=>!f.deleted);target.innerHTML=visible.length?`<p class="muted">Añadir esta película a:</p>${visible.map(f=>`<button class="secondary folder-choice" data-movie-folder="${esc(f.id)}">${esc(f.icon||'🎬')} ${esc(f.name)} ${f.movies.some(id=>Number(id)===Number(m.id))?'✓':''}</button>`).join('')}`:'<p class="muted">Aún no has creado colecciones. Créala desde el apartado Colecciones.</p>';target.querySelectorAll('[data-movie-folder]').forEach(b=>b.onclick=()=>{const f=folders.find(x=>x.id===b.dataset.movieFolder&&!x.deleted);if(!f)return;if(!f.movies.some(id=>Number(id)===Number(m.id))){f.movies.push(m.id);f.updatedAt=Math.max(Date.now(),Number(f.updatedAt||0)+1);commitFolders();toast('Añadida a '+f.name+'.');}else toast('Ya estaba en '+f.name+'.');target.hidden=true;});};
 if($('#ratingsHelp'))$('#ratingsHelp').onclick=()=>{$('#detail').close();tab='settings';render();};
 $('#personal').onsubmit=e=>{e.preventDefault();try{const score=parseScore($('#score').value),status=$('#status').value;if(status!=='seen')return;if(score===null){toast('Introduce tu nota antes de guardar.');$('#score').focus();return;}const ok=put(m.id,{movie:opened,status,score,date:$('#date').value,note:$('#note').value,chosenAt:0,skipUntil:0});if(ok){toast('Tu nota y comentario se han guardado.');$('#detail').close();render();}}catch(e){toast(e.message);}};
 $('#remove').onclick=()=>{if(tab==='folders'&&folderCurrent()?.movies.some(id=>Number(id)===m.id)){removeFromCurrentFolder(m.id);$('#detail').close();return;}const previous=rec(m.id)?{...rec(m.id)}:null;put(m.id,{deleted:true});$('#detail').close();render();saveUndo(m.id,previous);};}

// Carpetas independientes del estado de cada película; se sincronizan con la misma cuenta.
function folderStorageKey(){return 'poppy-folders-'+(cloudUser()?.id||'guest');}
function loadFolders(){try{folders=JSON.parse(localStorage.getItem(folderStorageKey())||'[]');if(!Array.isArray(folders))folders=[];folders=folders.map(normalizeFolder);}catch{folders=[];}}
function persistFolders(){localStorage.setItem(folderStorageKey(),JSON.stringify(folders));}
// Sincronización automática y segura de colecciones: captura la instantánea,
// conserva ediciones hechas mientras se espera a la red y reintenta al reconectar.
let foldersSyncing=false,foldersResync=false,foldersSyncTimer=null,foldersError='';
function scheduleFoldersSync(delay=700){
 if(!cloudEnabled()||!cloudUser())return;
 clearTimeout(foldersSyncTimer);
 foldersSyncTimer=setTimeout(()=>syncFolders(),delay);
}
async function syncFolders(){
 if(!cloudEnabled()||!cloudUser())return;
 if(foldersSyncing){foldersResync=true;return;}
 foldersSyncing=true;
 const scope=folderStorageKey(), snapshot=folders.map(f=>normalizeFolder({...f,movies:[...f.movies]}));
 try{
  const merged=await syncFoldersCloud(snapshot);
  if(scope!==folderStorageKey())return;
  // Si el usuario modifica una carpeta durante la petición, esa versión local prevalece
  // sobre la instantánea y se envía a la nube en la siguiente ronda.
  const current=new Map(folders.map(f=>[f.id,f]));
  const original=new Map(snapshot.map(f=>[f.id,f]));
  const result=new Map(merged.map(f=>[f.id,f]));
  let changedDuringFlight=false;
  for(const [id,f] of current){
   const previous=original.get(id);
   if(!previous||JSON.stringify(previous)!==JSON.stringify(f)){
    result.set(id,f);changedDuringFlight=true;
   }
  }
  folders=[...result.values()].map(normalizeFolder);persistFolders();
  foldersError='';
  if(changedDuringFlight)foldersResync=true;
  if(tab==='folders')foldersPage();
 }catch(e){
  const firstFailure=foldersError!==e.message;
  foldersError=e.message;
  console.warn('Sincronización de colecciones:',e.message);
  if(firstFailure&&tab==='folders'&&!document.hidden)toast('Las colecciones siguen guardadas aquí. '+e.message);
 }finally{
  foldersSyncing=false;
  if(foldersResync){foldersResync=false;scheduleFoldersSync(300);}
 }
}
function commitFolders(){
 try{persistFolders();}catch(e){toast('No se pudieron guardar las colecciones en el navegador.');return;}
 if(tab==='folders')foldersPage();
 scheduleFoldersSync(300);
}
function folderCurrent(){return folders.find(f=>f.id===folderId&&!f.deleted);}
function foldersPage(){const current=folderCurrent();if(!current){folderId=null;$('#main').innerHTML=`<span class="eyebrow">TU CINE ORGANIZADO</span><h1>Mis colecciones.</h1><p class="muted">Crea carpetas para tus maratones, tus favoritas o cualquier plan de cine.</p><form id="newFolderForm" class="filters"><input id="folderName" maxlength="70" required placeholder="Nombre de la nueva carpeta…" aria-label="Nombre de la colección"><button class="primary" type="submit">+ Crear carpeta</button></form><div class="folder-grid">${folders.filter(f=>!f.deleted).map(f=>`<button class="folder-card" data-folder="${esc(f.id)}">${folderVisual(f)}<div class="folder-card-body"><strong>${esc(f.name)}</strong><small>${f.movies.length} películas</small></div></button>`).join('')}</div>`;$('#newFolderForm').onsubmit=e=>{e.preventDefault();const name=$('#folderName').value.trim();if(!name)return;folders.push(normalizeFolder({id:crypto.randomUUID(),name,movies:[],updatedAt:Date.now(),icon:'🎬',banner:''}));commitFolders();};return;}
 const ids=new Set(current.movies.map(Number));const movies=current.movies.map(id=>getMovie(id)).filter(Boolean);$('#main').innerHTML=`<button class="textbtn" id="backFolders">← Mis colecciones</button><div class="collection-heading-wrap"><div class="folder-name-edit"><h1>${esc(current.name)}</h1><p class="muted">${movies.length} películas · Puedes añadir películas sin marcarlas como pendientes.</p><div class="actions compact"><button class="textbtn" id="renameFolder">Editar nombre</button><button class="textbtn" id="deleteFolder">Eliminar</button></div></div>${folderVisual(current,'cover')}</div><section class="panel folder-search"><h2>+ Añadir películas</h2><form id="folderSearchForm" class="filters"><input id="folderSearch" maxlength="150" value="${esc(folderQuery)}" placeholder="Buscar una película por título…" aria-label="Buscar películas para la colección"><button class="primary" type="submit">Buscar</button></form><div id="folderResults">${folderResults.map(m=>`<div class="folder-result"><button class="folder-result-title" data-movie="${m.id}">${esc(m.title)} <small>${esc(m.year)}</small></button><button class="secondary" data-folder-add="${m.id}">${ids.has(m.id)?'✓ Añadida':'+ Añadir'}</button></div>`).join('')}</div><button id="moreFolderResults" class="secondary" ${folderPage>=folderTotal||!folderQuery?'hidden':''}>Más resultados</button></section><details class="panel folder-customize"><summary>🎨 Personalizar carpeta</summary><div class="folder-customize-grid"><div><label for="folderNameEdit">Nombre</label><input id="folderNameEdit" maxlength="70" value="${esc(current.name)}" placeholder="Nombre de la colección"></div><div><label for="folderIcon">Icono</label><select id="folderIcon">${FOLDER_ICONS.map(icon=>`<option value="${icon}" ${icon===current.icon?'selected':''}>${icon} ${icon==='👩‍❤️‍👨'?'Parejita':icon==='❤️'?'Corazón':icon==='🎃'?'Calabaza':icon==='🎬'?'Cine':icon==='🍿'?'Palomitas':icon==='😱'?'Terror':icon==='🎄'?'Navidad':icon==='🌧️'?'Lluvia':icon==='✨'?'Brilli brilli':'Estrella'}</option>`).join('')}</select><p class="field-help">Puedes elegir, por ejemplo, una parejita, un corazón o una calabaza.</p></div><div><label for="folderBanner">Banner de la carpeta</label><input id="folderBanner" type="file" accept="image/*"><p class="field-help">Sube una imagen de tu galería. Se recorta en formato horizontal.</p></div><div>${folderVisual(current,'preview')}<div class="actions"><button class="primary" id="saveFolderStyle" type="button">Guardar estilo</button><button class="secondary" id="removeFolderBanner" type="button" ${current.banner?'':'disabled'}>Quitar banner</button></div></div></div></details><h2 class="folder-movies-heading">Películas de esta colección</h2>${movies.length?`<div class="grid">${movies.map(m=>`<div class="folder-movie-item">${card(m)}<button class="folder-remove" data-folder-remove="${m.id}" aria-label="Quitar ${esc(m.title)} de esta colección">× Quitar</button></div>`).join('')}</div>`:'<p class="muted">Todavía no hay películas en esta colección.</p>'}`;
 $('#backFolders').onclick=()=>{folderId=null;folderQuery='';folderResults=[];foldersPage();};$('#renameFolder').onclick=()=>{$('#folderNameEdit').focus();$('#folderNameEdit').select();};$('#deleteFolder').onclick=()=>{if(!confirm('¿Eliminar esta carpeta? Las películas seguirán en tus listas personales.'))return;current.deleted=true;current.updatedAt=Date.now();folderId=null;commitFolders();};$('#folderSearchForm').onsubmit=e=>{e.preventDefault();folderQuery=$('#folderSearch').value.trim();folderPage=1;folderFind(false);};$('#moreFolderResults').onclick=()=>folderFind(true);document.querySelectorAll('[data-folder-remove]').forEach(b=>b.onclick=()=>removeFromCurrentFolder(Number(b.dataset.folderRemove))); document.querySelectorAll('[data-folder-add]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.folderAdd);if(!current.movies.includes(id)){current.movies.push(id);current.updatedAt=Date.now();commitFolders();}else{current.movies=current.movies.filter(x=>x!==id);current.updatedAt=Date.now();commitFolders();}});
 $('#saveFolderStyle').onclick=async()=>{const name=$('#folderNameEdit').value.trim()||current.name;const icon=$('#folderIcon').value||'🎬';const file=$('#folderBanner').files[0];try{current.name=name.slice(0,70);current.icon=icon; if(file)current.banner=await compressFolderBanner(file);current.updatedAt=Date.now();commitFolders();toast('Carpeta personalizada.');}catch(e){toast(e.message);}};$('#removeFolderBanner').onclick=()=>{current.banner='';current.updatedAt=Date.now();commitFolders();toast('Banner eliminado.');};
}
async function folderFind(more){if(!folderQuery)return;const version=++folderRequest;try{const page=more?folderPage+1:1;const d=mode==='live'?await api('?q='+encodeURIComponent(folderQuery)+'&page='+page):{movies:seeds.filter(m=>m.title.toLocaleLowerCase('es').includes(folderQuery.toLocaleLowerCase('es'))),totalPages:1};if(version!==folderRequest||tab!=='folders')return;d.movies.forEach(putMovie);folderResults=more?[...new Map([...folderResults,...d.movies].map(m=>[m.id,m])).values()]:d.movies;folderPage=page;folderTotal=d.totalPages||1;foldersPage();}catch(e){toast(e.message);}}

function steps(){return `<ol><li>En Vercel abre tu proyecto → <b>Settings → Environment Variables</b>.</li><li>Añade <code>TMDB_READ_TOKEN</code> con el <b>Token de acceso de lectura a la API</b> de <a href="https://www.themoviedb.org/settings/api" target="_blank" rel="noopener">TMDB</a>.</li><li>Para las notas automáticas, añade <code>MDBLIST_API_KEY</code> de <a href="https://mdblist.com/preferences/" target="_blank" rel="noopener">MDBList → Preferences</a>.</li><li>Guarda y abre <b>Deployments → Redeploy</b>. Después recarga Poppy.</li></ol><p class="muted">Las claves se guardan en Vercel, nunca en GitHub.</p>`;}
function settings(){$('#main').innerHTML=`<span class="eyebrow">TU CINE, A TU MANERA</span><h1>Entre bambalinas.</h1><section class="panel"><h2>Conexiones</h2><div class="connection"><b>Catálogo y fotos · TMDB</b><span>${mode==='live'?'Conectado ✓':mode==='connecting'?'Comprobando…':'Sin conexión'}</span></div><div class="connection"><b>Notas · MDBList</b><span>${config.mdb?'Clave configurada; se comprobará al abrir una ficha':'Falta configurar'}</span></div>${apiError?`<p class="notice">${esc(apiError)}</p>`:''}<button id="check" class="secondary">Comprobar conexión</button><details ${mode!=='live'?'open':''}><summary>Cómo activar el catálogo y las puntuaciones</summary>${steps()}</details></section><section class="panel"><h2>Tu cuenta y sincronización</h2><p id="syncStatus" role="status">${esc(syncStatus)}</p><p class="muted">Sincronización automática de películas, notas y colecciones entre tus dispositivos. Al recuperar conexión se reintenta automáticamente.</p>${foldersError?`<p class="notice">Colecciones: ${esc(foldersError)}</p>`:''}${cloudEnabled()?cloudUser()?`<p>Sesión: <b>${esc(cloudUser().email)}</b></p><div class="actions"><button class="primary" id="sync">Sincronizar ahora</button><button class="secondary" id="importGuest">Añadir mis listas de este navegador</button><button class="secondary" id="logout">Cerrar sesión</button></div><p class="muted">Las cuentas tienen colecciones separadas. Al cerrar sesión vuelves a la colección local.</p>`:`<form id="loginForm"><label for="email">Correo</label><input id="email" type="email" required autocomplete="email"><label for="password">Contraseña</label><input id="password" type="password" minlength="8" required autocomplete="current-password"><div class="actions"><button class="primary" type="submit">Entrar</button><button class="secondary" id="signup" type="button">Crear cuenta</button></div><p class="muted">Usa la misma cuenta en móvil y ordenador. La colección local solo se añade a tu cuenta si pulsas «Añadir mis listas de este navegador».</p></form>`:'<p>Ahora tus datos se guardan en este navegador. La sincronización está preparada, pero necesita un proyecto de Supabase.</p><details><summary>Activar la sincronización</summary><ol><li>Crea un proyecto en <a href="https://supabase.com/dashboard" target="_blank" rel="noopener">Supabase</a>.</li><li>En SQL Editor ejecuta el archivo <code>supabase.sql</code> incluido con Poppy.</li><li>En Vercel añade <code>SUPABASE_URL</code> (Project URL) y <code>SUPABASE_ANON_KEY</code> (clave publishable o anon pública).</li><li>Haz Redeploy. Aquí aparecerá el formulario para crear tu cuenta.</li></ol><p>No uses una clave secret ni service_role. Tu cuenta tendrá acceso únicamente a sus propios datos.</p></details>'}</section><section class="panel"><h2>Tus copias de seguridad</h2><p>Las copias sirven también para conservar tus datos antes de cambiar de dominio o borrar el navegador.</p><div class="actions"><button class="primary" id="export">Descargar copia</button><label class="secondary" style="margin:0;cursor:pointer">Importar copia<input id="import" type="file" accept="application/json,.json" hidden></label></div><p class="muted">Importar combina las listas. Para una película repetida se utiliza la copia importada. Se admiten copias de la primera versión.</p></section><section class="panel"><h2>Tus preferencias</h2><p>Las recomendaciones dan más peso a los géneros que puntúas bien y menos a los que puntúas bajo. «Sorpréndeme» elige entre todos los candidatos. No se necesita una clave de IA.</p><button class="secondary" data-tab="dismissed">Revisar películas descartadas</button><button class="textbtn" id="resetLater">Volver a mostrar las de «hoy no»</button></section><section class="panel"><h2>Créditos</h2><a href="https://www.themoviedb.org/" target="_blank" rel="noopener">TMDB — The Movie Database</a><p>This product uses the TMDB API but is not endorsed or certified by TMDB.</p><p class="muted">Datos e imágenes: TMDB. Puntuaciones: MDBList y, opcionalmente, OMDb. Poppy no reproduce películas.</p></section>`;
 $('#check').onclick=()=>connect();$('#resetLater').onclick=()=>{for(const [id,r] of Object.entries(records))if(!r.deleted&&r.skipUntil)put(id,{skipUntil:0});toast('Vuelven a estar disponibles.');};
 $('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:2,records,folders},null,2)],{type:'application/json'}));a.download='poppy-copia-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Máximo 10 MB.');const parsed=JSON.parse(await file.text());const incoming=validateBackup(parsed);for(const [id,r] of Object.entries(incoming))put(id,r);if(Array.isArray(parsed.folders)){for(const folder of parsed.folders.map(normalizeFolder)){const i=folders.findIndex(f=>f.id===folder.id);if(i<0||folder.updatedAt>folders[i].updatedAt)folders[i<0?folders.length:i]=folder;}commitFolders();}render();toast('Copia importada.');}catch(e){toast(e.message);}};
 if($('#sync'))$('#sync').onclick=async()=>{await syncNow(true);await syncFolders();};
 if($('#logout'))$('#logout').onclick=async()=>{await logout();storeKey='poppy-v2-guest';dirty.clear();loadRecords();loadFolders();foldersError='';syncStatus='Solo en este navegador';pick=null;render();};
 if($('#importGuest'))$('#importGuest').onclick=()=>{try{const raw=localStorage.getItem('poppy-v2-guest')||localStorage.getItem('poppy-v1');if(!raw)return toast('No hay listas locales para añadir.');const guest=validateBackup(JSON.parse(raw));let n=0;for(const [id,r] of Object.entries(guest))if(!records[id]&&!r.deleted){put(id,r);n++;}toast(n+' películas añadidas; las existentes en tu cuenta se han conservado.');syncNow();}catch(e){toast(e.message);}};
 const authenticate=async create=>{const form=$('#loginForm');if(!form.reportValidity())return;const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{const email=$('#email').value.trim(),password=$('#password').value;if(create&&!await signup(email,password)){toast('Revisa tu correo para confirmar la cuenta. Después pulsa Entrar.');return;}if(!create)await login(email,password);switchAccount();render();await syncNow(true);}catch(e){toast(e.message);}finally{buttons.forEach(b=>b.disabled=false);}};
 if($('#loginForm'))$('#loginForm').onsubmit=e=>{e.preventDefault();authenticate(false);};if($('#signup'))$('#signup').onclick=()=>authenticate(true);
}
function switchAccount(){storeKey=cloudUser()?'poppy-v2-user-'+cloudUser().id:'poppy-v2-guest';dirty.clear();loadRecords();loadFolders();scheduleFoldersSync(100);pick=null;syncStatus=cloudUser()?'Cuenta conectada; sincronización pendiente':'Solo en este navegador';}
async function syncNow(show=false){if(syncing||!cloudEnabled()||!cloudUser())return;syncing=true;const scope=storeKey,snapshot={...records};syncStatus='Sincronizando…';if($('#syncStatus'))$('#syncStatus').textContent=syncStatus;try{const remote=await syncRecords(snapshot);if(scope!==storeKey)return;records=mergeRecords(remote,records);if(!persist())throw Error('Se han recibido tus datos, pero el navegador no permite guardarlos. Descarga una copia.');for(const id of [...dirty])if(snapshot[id]?.updatedAt===records[id]?.updatedAt)dirty.delete(id);syncStatus='Sincronizado a las '+new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'});if(show)toast('Tus listas están sincronizadas.');if(!$('#detail').open&&tab!=='search')render();}catch(e){if(scope===storeKey){syncStatus=e.message;if(show)toast(e.message);}}finally{syncing=false;if($('#syncStatus'))$('#syncStatus').textContent=syncStatus;if(dirty.size&&scope===storeKey){clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow(),5000);}}}
async function connect(){mode='connecting';apiError='';if(tab==='settings')settings();try{const r=await fetch('./api/config',{cache:'no-store'});if(r.ok){config=await r.json();configureCloud(config.supabase);if(cloudUser()&&cloudEnabled()&&storeKey==='poppy-v2-guest')switchAccount();}const d=await api('');config.genres=d.genres;catalog=d.movies;searchResults=[];totalPages=d.totalPages||1;mode='live';pick=null;
 // Replace stale demo posters with current metadata, without altering personal notes.
 const saved=activeRecords().filter(r=>r.movie.demo||isStale(r.movie)).slice(0,20);
 for(let i=0;i<saved.length;i+=4){await Promise.all(saved.slice(i,i+4).map(async r=>{try{const fresh=await api('?id='+r.movie.id);putMovie(fresh);if(rec(fresh.id))records[fresh.id].movie=fresh;}catch{}}));}persist();
 // Descubrimiento general filtrado por géneros: evitamos recomendaciones basadas en títulos parecidos.
 const favourites=Object.entries(taste(records)).filter(([,score])=>score>0).sort((a,b)=>b[1]-a[1]).slice(0,3);
 await Promise.all(favourites.map(async ([name])=>{const gid=Object.entries(config.genres||{}).find(([,g])=>g===name)?.[0];if(!gid)return;try{(await api('?genre='+gid+'&page=1')).movies.forEach(putMovie);}catch{}}));
 }catch(e){mode='demo';apiError=e.message;catalog=seeds;}if(!$('#detail').open)render();if(cloudUser()&&cloudEnabled()){syncNow();scheduleFoldersSync(150);}}
document.addEventListener('click',e=>{const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;searchVersion++;render();}const action=e.target.closest('[data-action]');if(action){const id=Number(action.dataset.id),type=action.dataset.action;if(type==='finish'){openMovie(id,true);return;}if(type==='choose'){if(rec(id)?.status==='seen')return toast('Ya la has visto. Elige una pendiente para este finde.');for(const [other,r] of Object.entries(records))if(!r.deleted&&r.chosenAt)put(other,{chosenAt:0});put(id,{movie:getMovie(id),status:'pending',chosenAt:Date.now(),skipUntil:0});toast('Reservada para tu próxima sesión.');}if(type==='unchoose')put(id,{chosenAt:0});if(type==='later'){const d=new Date();d.setDate(d.getDate()+1);d.setHours(0,0,0,0);put(id,{skipUntil:d.getTime(),chosenAt:0});choose();toast('Mañana podrá volver a salir.');}if($('#detail').open)$('#detail').close();render();}const f=e.target.closest('[data-folder]');if(f){folderId=f.dataset.folder;folderResults=[];folderQuery='';foldersPage();const missing=folderCurrent()?.movies.filter(id=>!getMovie(id)).slice(0,60)||[];if(mode==='live'&&missing.length){Promise.all(missing.map(id=>api('?id='+id).then(putMovie).catch(()=>null))).then(()=>{if(tab==='folders'&&folderCurrent())foldersPage();});}}const m=e.target.closest('[data-movie]');if(m)openMovie(m.dataset.movie);});
document.addEventListener('change',e=>{if(e.target.matches('[data-select]')){const id=Number(e.target.dataset.select);if(e.target.checked)selected.add(id);else selected.delete(id);if($('#selectionCount'))$('#selectionCount').textContent=selected.size;}});
$('.brand').onclick=e=>{e.preventDefault();tab='home';render();};$('.close').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>detailVersion++);
window.addEventListener('storage',e=>{if(e.key===storeKey&&e.newValue){try{records=mergeRecords(records,validateBackup(JSON.parse(e.newValue)));if(!$('#detail').open&&tab!=='search')render();}catch{}}});function refreshCloud(){if(!cloudEnabled()||!cloudUser())return;syncNow();scheduleFoldersSync(50);}
window.addEventListener('online',refreshCloud);
window.addEventListener('focus',refreshCloud);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshCloud();});
window.addEventListener('pageshow',refreshCloud);
window.addEventListener('storage',e=>{
 if(e.key===folderStorageKey()&&e.newValue){
  try{const incoming=JSON.parse(e.newValue);if(Array.isArray(incoming)){
    const all=new Map(folders.map(f=>[f.id,f]));
    for(const f of incoming.map(normalizeFolder))if(!all.has(f.id)||f.updatedAt>all.get(f.id).updatedAt)all.set(f.id,f);
    folders=[...all.values()].map(normalizeFolder);if(tab==='folders')foldersPage();
  }}catch{}
 }
});
